  'aun-data-retention',
  '37 4 * * *',
  $cron$
    delete from public.analytics_events
    where occurred_at < now() - interval '90 days';

    delete from public.user_notifications
    where
      (read_at is not null and read_at < now() - interval '90 days')
      or created_at < now() - interval '180 days';

